-- Tables ----------------------------------------------------------------
create table public."chat_participants" (
  "room_id" uuid not null,
  "user_id" uuid not null,
  "joined_at" timestamp with time zone default timezone('utc'::text, now()) not null,
  "last_read_at" timestamp with time zone default timezone('utc'::text, now()),
  constraint "chat_participants_pkey" PRIMARY KEY (room_id, user_id)
);

create table public."chat_rooms" (
  "id" uuid default gen_random_uuid() not null,
  "is_group" boolean default false,
  "name" text,
  "created_at" timestamp with time zone default timezone('utc'::text, now()) not null,
  "created_by" uuid default auth.uid(),
  constraint "chat_rooms_pkey" PRIMARY KEY (id)
);

create table public."follows" (
  "follower_id" uuid not null,
  "following_id" uuid not null,
  "created_at" timestamp with time zone default timezone('utc'::text, now()) not null,
  constraint "follows_pkey" PRIMARY KEY (follower_id, following_id)
);

create table public."messages" (
  "id" uuid default gen_random_uuid() not null,
  "room_id" uuid not null,
  "sender_id" uuid not null,
  "content" text not null,
  "created_at" timestamp with time zone default timezone('utc'::text, now()) not null,
  "workout_id" uuid,
  "image_url" text,
  constraint "messages_pkey" PRIMARY KEY (id)
);

create table public."notification_preferences" (
  "user_id" uuid not null,
  "likes" boolean default true not null,
  "comments" boolean default true not null,
  "follows" boolean default true not null,
  "new_posts" boolean default true not null,
  "chats" boolean default true not null,
  "daily_roast" boolean default true not null,
  "push_enabled" boolean default true not null,
  "updated_at" timestamp with time zone default now() not null,
  constraint "notification_preferences_pkey" PRIMARY KEY (user_id)
);

create table public."notifications" (
  "id" uuid default gen_random_uuid() not null,
  "recipient_id" uuid not null,
  "type" text not null,
  "aggregation_key" text not null,
  "actor_count" integer default 1 not null,
  "last_actor_id" uuid,
  "workout_id" uuid,
  "comment_id" uuid,
  "preview" text,
  "read_at" timestamp with time zone,
  "created_at" timestamp with time zone default now() not null,
  "updated_at" timestamp with time zone default now() not null,
  "room_id" uuid,
  constraint "notifications_recipient_id_aggregation_key_key" UNIQUE (recipient_id, aggregation_key),
  constraint "notifications_pkey" PRIMARY KEY (id),
  constraint "notifications_type_check" CHECK ((type = ANY (ARRAY['like'::text, 'comment'::text, 'follow'::text, 'new_post'::text, 'chat'::text])))
);

create table public."profiles" (
  "id" uuid not null,
  "username" text,
  "display_name" text,
  "avatar_url" text,
  "created_at" timestamp with time zone default timezone('utc'::text, now()) not null,
  "expo_push_token" text,
  "bio" text,
  constraint "profiles_username_key" UNIQUE (username),
  constraint "profiles_pkey" PRIMARY KEY (id)
);

create table public."web_push_subscriptions" (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid not null,
  "endpoint" text not null,
  "p256dh" text not null,
  "auth" text not null,
  "user_agent" text,
  "created_at" timestamp with time zone default now() not null,
  constraint "web_push_subscriptions_user_id_endpoint_key" UNIQUE (user_id, endpoint),
  constraint "web_push_subscriptions_pkey" PRIMARY KEY (id)
);

create table public."workout_comments" (
  "id" uuid default gen_random_uuid() not null,
  "workout_id" uuid not null,
  "user_id" uuid not null,
  "content" text not null,
  "created_at" timestamp with time zone default now() not null,
  constraint "workout_comments_pkey" PRIMARY KEY (id),
  constraint "workout_comments_content_check" CHECK (((length(content) >= 1) AND (length(content) <= 500)))
);

create table public."workout_likes" (
  "workout_id" uuid not null,
  "user_id" uuid not null,
  "created_at" timestamp with time zone default now() not null,
  constraint "workout_likes_pkey" PRIMARY KEY (workout_id, user_id)
);

create table public."workout_views" (
  "workout_id" uuid not null,
  "viewer_id" uuid not null,
  "viewed_at" timestamp with time zone default now() not null,
  constraint "workout_views_pkey" PRIMARY KEY (workout_id, viewer_id)
);

create table public."workouts" (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid not null,
  "activity_type" text,
  "duration_minutes" integer not null,
  "notes" text,
  "image_url" text,
  "created_at" timestamp with time zone default timezone('utc'::text, now()) not null,
  "distance" text,
  "calories" integer default 0,
  constraint "workouts_pkey" PRIMARY KEY (id)
);

