CREATE INDEX notifications_unread_idx ON public.notifications USING btree (recipient_id) WHERE (read_at IS NULL);
CREATE INDEX web_push_subscriptions_user_idx ON public.web_push_subscriptions USING btree (user_id);
CREATE INDEX workout_comments_workout_idx ON public.workout_comments USING btree (workout_id, created_at);
CREATE INDEX workout_likes_user_idx ON public.workout_likes USING btree (user_id);
CREATE INDEX workout_likes_workout_idx ON public.workout_likes USING btree (workout_id);
CREATE INDEX workout_views_workout_idx ON public.workout_views USING btree (workout_id);

-- Functions -------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.actor_name(p_user_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(display_name, username, 'Someone')
  from public.profiles
  where id = p_user_id;
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_chat_rooms()
 RETURNS SETOF uuid
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
  select room_id from public.chat_participants where user_id = auth.uid();
$function$
;

CREATE OR REPLACE FUNCTION public.notif_pref(p_user_id uuid, p_pref text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_value boolean;
begin
  execute format('select %I from notification_preferences where user_id = $1', p_pref)
    into v_value
    using p_user_id;
  return coalesce(v_value, true);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.on_follow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor text;
begin
  if new.follower_id = new.following_id then return new; end if;
  if not public.notif_pref(new.following_id, 'follows') then return new; end if;

  perform public.upsert_notification(
    new.following_id, 'follow', 'follow:' || new.follower_id::text,
    new.follower_id, null, null, null
  );

  v_actor := public.actor_name(new.follower_id);
  perform public.send_push_notification(
    new.following_id,
    'Locked In',
    v_actor || ' started following you',
    jsonb_build_object('type', 'follow', 'actor_id', new.follower_id)
  );
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.on_message_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_preview text;
  v_actor text;
begin
  if new.content is not null and length(new.content) > 0 then
    v_preview := left(new.content, 80);
  elsif new.image_url is not null then
    v_preview := '📷 Photo';
  elsif new.workout_id is not null then
    v_preview := '🏋️ Shared a workout';
  else
    v_preview := 'New message';
  end if;

  v_actor := public.actor_name(new.sender_id);

  for r in
    select user_id from public.chat_participants
    where room_id = new.room_id and user_id <> new.sender_id
  loop
    if public.notif_pref(r.user_id, 'chats') then
      perform public.upsert_chat_notification(
        r.user_id,
        'chat:' || new.room_id::text || ':' || new.sender_id::text,
        new.sender_id, new.room_id, v_preview
      );
      perform public.send_push_notification(
        r.user_id,
        v_actor,
        v_preview,
        jsonb_build_object('type', 'chat', 'room_id', new.room_id, 'actor_id', new.sender_id)
      );
    end if;
  end loop;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.on_workout_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner_id uuid;
  v_actor    text;
begin
  select user_id into v_owner_id from public.workouts where id = new.workout_id;
  if v_owner_id is null or v_owner_id = new.user_id then return new; end if;
  if not public.notif_pref(v_owner_id, 'comments') then return new; end if;

  perform public.upsert_notification(
    v_owner_id, 'comment',
    'comment:' || new.workout_id::text || ':' || new.user_id::text,
    new.user_id, new.workout_id, new.id, left(new.content, 80)
  );

  v_actor := public.actor_name(new.user_id);
  perform public.send_push_notification(
    v_owner_id,
    v_actor,
    'commented: ' || left(new.content, 100),
    jsonb_build_object('type', 'comment', 'workout_id', new.workout_id, 'comment_id', new.id, 'actor_id', new.user_id)
  );
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.on_workout_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  v_actor text;
begin
  v_actor := public.actor_name(new.user_id);
  for r in
    select follower_id from public.follows where following_id = new.user_id
  loop
    if public.notif_pref(r.follower_id, 'new_posts') then
      perform public.upsert_notification(
        r.follower_id, 'new_post', 'post:' || new.id::text,
        new.user_id, new.id, null, null
      );
      perform public.send_push_notification(
        r.follower_id,
        'Locked In',
        v_actor || ' posted a new workout',
        jsonb_build_object('type', 'new_post', 'workout_id', new.id, 'actor_id', new.user_id)
      );
    end if;
  end loop;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.on_workout_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner_id uuid;
  v_actor    text;
begin
  select user_id into v_owner_id from public.workouts where id = new.workout_id;
  if v_owner_id is null or v_owner_id = new.user_id then return new; end if;
  if not public.notif_pref(v_owner_id, 'likes') then return new; end if;

  perform public.upsert_notification(
    v_owner_id, 'like', 'like:' || new.workout_id::text,
    new.user_id, new.workout_id, null, null
  );

  v_actor := public.actor_name(new.user_id);
  perform public.send_push_notification(
    v_owner_id,
    'Locked In',
    v_actor || ' liked your workout',
    jsonb_build_object('type', 'like', 'workout_id', new.workout_id, 'actor_id', new.user_id)
  );
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.on_workout_unlike()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_owner_id    uuid;
  v_other_count int;
begin
  select user_id into v_owner_id from public.workouts where id = old.workout_id;
  if v_owner_id is null or v_owner_id = old.user_id then
    return old;
  end if;

  -- Are there other likes on this post?
  select count(*) into v_other_count
    from public.workout_likes
    where workout_id = old.workout_id and user_id <> old.user_id;

  if v_other_count = 0 then
    delete from public.notifications
      where recipient_id = v_owner_id
        and aggregation_key = 'like:' || old.workout_id::text;
  else
    -- Just decrement the count; pick a remaining liker to display
    update public.notifications
      set actor_count = greatest(actor_count - 1, 1),
          last_actor_id = (
            select user_id from public.workout_likes
            where workout_id = old.workout_id and user_id <> old.user_id
            order by created_at desc limit 1
          ),
          updated_at = now()
      where recipient_id = v_owner_id
        and aggregation_key = 'like:' || old.workout_id::text;
  end if;

  return old;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.send_push_notification(p_recipient_id uuid, p_title text, p_body text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_expo_token text;
  v_push_enabled boolean;
begin
  -- Master push toggle from notification_preferences. Defaults to true if no row.
  select coalesce(push_enabled, true) into v_push_enabled
    from public.notification_preferences
    where user_id = p_recipient_id;
  if v_push_enabled is null then v_push_enabled := true; end if;
  if not v_push_enabled then return; end if;

  select expo_push_token into v_expo_token
    from public.profiles
    where id = p_recipient_id;

  if v_expo_token is null or length(v_expo_token) = 0 then
    return;
  end if;

  perform net.http_post(
    url := 'https://exp.host/--/api/v2/push/send',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Accept', 'application/json',
      'Accept-encoding', 'gzip, deflate'
    ),
    body := jsonb_build_object(
      'to', v_expo_token,
      'sound', 'default',
      'title', p_title,
      'body', p_body,
      'data', p_data,
      'priority', 'high',
      'channelId', 'default'
    )
  );
end;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_chat_notification(p_recipient_id uuid, p_aggregation_key text, p_actor_id uuid, p_room_id uuid, p_preview text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.notifications
    (recipient_id, type, aggregation_key, actor_count, last_actor_id,
     room_id, preview, created_at, updated_at)
  values
    (p_recipient_id, 'chat', p_aggregation_key, 1, p_actor_id,
     p_room_id, p_preview, now(), now())
  on conflict (recipient_id, aggregation_key) do update
    set actor_count   = notifications.actor_count + 1,
        last_actor_id = excluded.last_actor_id,
        preview       = excluded.preview,           -- show the latest message
        read_at       = null,
        updated_at    = now();
end;
$function$
;

CREATE OR REPLACE FUNCTION public.upsert_notification(p_recipient_id uuid, p_type text, p_aggregation_key text, p_actor_id uuid, p_workout_id uuid, p_comment_id uuid, p_preview text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.notifications
    (recipient_id, type, aggregation_key, actor_count, last_actor_id,
     workout_id, comment_id, preview, created_at, updated_at)
  values
    (p_recipient_id, p_type, p_aggregation_key, 1, p_actor_id,
     p_workout_id, p_comment_id, p_preview, now(), now())
  on conflict (recipient_id, aggregation_key) do update
    set actor_count   = case
                          when notifications.last_actor_id = excluded.last_actor_id
                            then notifications.actor_count
                          else notifications.actor_count + 1
                        end,
        last_actor_id = excluded.last_actor_id,
        comment_id    = coalesce(excluded.comment_id, notifications.comment_id),
        preview       = coalesce(excluded.preview, notifications.preview),
        read_at       = null,                  -- mark unread again on new activity
        updated_at    = now();
end;
$function$
;

-- Triggers --------------------------------------------------------------
CREATE TRIGGER trg_on_follow AFTER INSERT ON public.follows FOR EACH ROW EXECUTE FUNCTION on_follow();
CREATE TRIGGER trg_on_message_insert AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION on_message_insert();
CREATE TRIGGER trg_on_workout_comment AFTER INSERT ON public.workout_comments FOR EACH ROW EXECUTE FUNCTION on_workout_comment();
CREATE TRIGGER trg_on_workout_like AFTER INSERT ON public.workout_likes FOR EACH ROW EXECUTE FUNCTION on_workout_like();
CREATE TRIGGER trg_on_workout_unlike AFTER DELETE ON public.workout_likes FOR EACH ROW EXECUTE FUNCTION on_workout_unlike();
CREATE TRIGGER trg_on_workout_insert AFTER INSERT ON public.workouts FOR EACH ROW EXECUTE FUNCTION on_workout_insert();

-- Row-level security ----------------------------------------------------
alter table public."chat_participants" enable row level security;
alter table public."chat_rooms" enable row level security;
alter table public."follows" enable row level security;
alter table public."messages" enable row level security;
alter table public."notification_preferences" enable row level security;
alter table public."notifications" enable row level security;
alter table public."profiles" enable row level security;
alter table public."web_push_subscriptions" enable row level security;
alter table public."workout_comments" enable row level security;
alter table public."workout_likes" enable row level security;
alter table public."workout_views" enable row level security;
alter table public."workouts" enable row level security;

create policy "Users can add participants" on public."chat_participants"
  as permissive
  for insert
  to public
  with check (true);

create policy "Users can update their own read status" on public."chat_participants"
  as permissive
  for update
  to public
  using ((user_id = auth.uid()));

create policy "Users can view participants of their rooms" on public."chat_participants"
  as permissive
  for select
  to public
  using ((room_id IN ( SELECT get_my_chat_rooms() AS get_my_chat_rooms)));

create policy "Creators can view their own rooms" on public."chat_rooms"
  as permissive
  for select
  to public
  using ((auth.uid() = created_by));

create policy "Users can create rooms" on public."chat_rooms"
  as permissive
  for insert
  to public
  with check (true);

create policy "Users can delete rooms they are in" on public."chat_rooms"
  as permissive
  for delete
  to public
  using ((EXISTS ( SELECT 1
   FROM chat_participants
  WHERE ((chat_participants.room_id = chat_rooms.id) AND (chat_participants.user_id = auth.uid())))));

create policy "Users can view rooms they are in" on public."chat_rooms"
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM chat_participants
  WHERE ((chat_participants.room_id = chat_rooms.id) AND (chat_participants.user_id = auth.uid())))));

create policy "Follows are viewable by everyone." on public."follows"
  as permissive
  for select
  to public
  using (true);

create policy "Users can follow others." on public."follows"
  as permissive
  for insert
  to public
  with check ((auth.uid() = follower_id));

create policy "Users can unfollow." on public."follows"
  as permissive
  for delete
  to public
  using ((auth.uid() = follower_id));

create policy "Users can read messages in their rooms" on public."messages"
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM chat_participants
  WHERE ((chat_participants.room_id = messages.room_id) AND (chat_participants.user_id = auth.uid())))));

create policy "Users can send messages to their rooms" on public."messages"
  as permissive
  for insert
  to public
  with check (((EXISTS ( SELECT 1
   FROM chat_participants
  WHERE ((chat_participants.room_id = messages.room_id) AND (chat_participants.user_id = auth.uid())))) AND (auth.uid() = sender_id)));

create policy "users insert their own prefs" on public."notification_preferences"
  as permissive
  for insert
  to authenticated
